module TopModule (
    input  logic       clk,
    input  logic       in,
    input  logic       reset,
    output logic [7:0] out_byte,
    output logic       done
);

    typedef enum logic [3:0] {
        IDLE  = 4'd0,
        B0    = 4'd1,
        B1    = 4'd2,
        B2    = 4'd3,
        B3    = 4'd4,
        B4    = 4'd5,
        B5    = 4'd6,
        B6    = 4'd7,
        B7    = 4'd8,
        STOP  = 4'd9,
        WAIT  = 4'd10
    } state_t;

    state_t state, next_state;
    logic [7:0] byte_d;

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            byte_d <= 8'h00;
        end else begin
            state <= next_state;
            if (state == B0) byte_d[0] <= in;
            if (state == B1) byte_d[1] <= in;
            if (state == B2) byte_d[2] <= in;
            if (state == B3) byte_d[3] <= in;
            if (state == B4) byte_d[4] <= in;
            if (state == B5) byte_d[5] <= in;
            if (state == B6) byte_d[6] <= in;
            if (state == B7) byte_d[7] <= in;
        end
    end

    always_comb begin
        next_state = state;
        done = 1'b0;
        case (state)
            IDLE: begin
                if (!in)
                    next_state = B0;
            end
            B0: next_state = B1;
            B1: next_state = B2;
            B2: next_state = B3;
            B3: next_state = B4;
            B4: next_state = B5;
            B5: next_state = B6;
            B6: next_state = B7;
            B7: next_state = STOP;
            STOP: begin
                if (in) begin
                    done = 1'b1;
                    next_state = IDLE;
                end else begin
                    next_state = WAIT;
                end
            end
            WAIT: begin
                if (in)
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign out_byte = byte_d;

endmodule

