module tb_TopModule;
    logic clk;
    logic in;
    logic reset;
    logic [7:0] out_byte;
    logic done;

    TopModule dut (
        .clk(clk),
        .in(in),
        .reset(reset),
        .out_byte(out_byte),
        .done(done)
    );

    always #5 clk = ~clk;

    // Task to send a byte
    // Format: start (0) + 8 data bits (LSB first) + stop (1 or 0)
    task send_frame(input [7:0] data, input stop_bit);
        integer i;
        begin
            // Start bit
            in = 1'b0;
            @(posedge clk);
            // 8 data bits, LSB first
            for (i = 0; i < 8; i = i + 1) begin
                in = data[i];
                @(posedge clk);
            end
            // Stop bit
            in = stop_bit;
            @(posedge clk);
            // Return line to idle (1)
            in = 1'b1;
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        in = 1;
        #12;
        reset = 0;
        #10;

        // Test 1: Send byte 8'hA5 (10100101) with correct stop bit (1)
        $display("Sending 0xA5 with correct stop bit...");
        send_frame(8'hA5, 1'b1);

        // Wait a couple cycles and check
        @(posedge clk);
        if (!done || out_byte !== 8'hA5) begin
            $display("SELFTEST FAIL: Expected out_byte = 0xA5, done = 1. Got out_byte = 0x%0h, done = %0b", out_byte, done);
            $finish;
        end

        // Test 2: Send byte 8'h3C (00111100) with correct stop bit (1)
        $display("Sending 0x3C with correct stop bit...");
        send_frame(8'h3C, 1'b1);
        @(posedge clk);
        if (!done || out_byte !== 8'h3C) begin
            $display("SELFTEST FAIL: Expected out_byte = 0x3C, done = 1. Got out_byte = 0x%0h, done = %0b", out_byte, done);
            $finish;
        end

        // Test 3: Send byte with bad stop bit (0), then wait for line to go high (stop bit found), then send next byte
        $display("Sending 0x55 with bad stop bit (0)...");
        send_frame(8'h55, 1'b0);

        // At this point, should be in WAIT state. done should NOT be high.
        @(posedge clk);
        if (done) begin
            $display("SELFTEST FAIL: done asserted on bad stop bit!");
            $finish;
        end

        // Keep line low for a cycle, then make it high (finding stop bit)
        in = 1'b0;
        @(posedge clk);
        in = 1'b1; // Stop bit found
        @(posedge clk);

        // Now send a valid byte 8'hFF
        $display("Sending 0xFF with correct stop bit after recovery...");
        send_frame(8'hFF, 1'b1);
        @(posedge clk);
        if (!done || out_byte !== 8'hFF) begin
            $display("SELFTEST FAIL: Expected out_byte = 0xFF after recovery, done = 1. Got out_byte = 0x%0h, done = %0b", out_byte, done);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

