module tb_TopModule;
    logic clk;
    logic in;
    logic reset;
    logic [7:0] out_byte;
    logic done;

    TopModule dut (
        .clk(clk),
        .in(in),
        .reset(reset),
        .out_byte(out_byte),
        .done(done)
    );

    always #5 clk = ~clk;

    task send_frame(input [7:0] data, input stop_bit, output logic got_done);
        integer i;
        begin
            got_done = 0;
            @(negedge clk);
            in = 1'b0; // Start bit
            @(posedge clk);

            for (i = 0; i < 8; i = i + 1) begin
                @(negedge clk);
                in = data[i];
                @(posedge clk);
            end

            @(negedge clk);
            in = stop_bit; // Stop bit
            @(posedge clk);

            // In this posedge clock cycle, done should be asserted if stop_bit == 1
            if (done) got_done = 1;
            if (done && (out_byte !== data)) begin
                $display("SELFTEST FAIL: data mismatch! Expected 0x%0h, got 0x%0h", data, out_byte);
            end

            @(negedge clk);
            in = 1'b1; // Idle
        end
    endtask

    initial begin
        logic gd;
        clk = 0;
        reset = 1;
        in = 1;
        #15;
        reset = 0;
        #10;

        // Test 1: Send byte 8'hA5 (10100101) with correct stop bit (1)
        $display("Sending 0xA5 with correct stop bit...");
        send_frame(8'hA5, 1'b1, gd);
        if (!gd) begin
            $display("SELFTEST FAIL: Expected done for 0xA5");
            $finish;
        end

        // Test 2: Send byte 8'h3C (00111100) with correct stop bit (1)
        $display("Sending 0x3C with correct stop bit...");
        send_frame(8'h3C, 1'b1, gd);
        if (!gd) begin
            $display("SELFTEST FAIL: Expected done for 0x3C");
