        // Line goes high (stop bit found)
        @(negedge clk);
        in = 1'b1;
        @(posedge clk);

        // Now send a valid byte 8'hFF
        $display("Sending 0xFF with correct stop bit after recovery...");
        send_frame(8'hFF, 1'b1, gd);
        if (!gd) begin
            $display("SELFTEST FAIL: Expected done for 0xFF after recovery");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
